23	export type AuthMethod = 'api-key' | 'email' | 'none';
24	
25	export interface UserAuthInfo {
26	  email: string | null;
27	  isLoggedIntoCloud: boolean;
28	  authMethod: AuthMethod;
29	}
30	
31	export function getUserAuthInfo(): UserAuthInfo {
32	  const globalConfig = readGlobalConfig();
33	  const email = globalConfig?.account?.email || null;
34	  const isLoggedIntoCloud = !!(globalConfig?.cloud?.apiKey || process.env.PROMPTFOO_API_KEY);
35	
36	  return {
37	    email,
38	    isLoggedIntoCloud,
39	    authMethod: isLoggedIntoCloud ? 'api-key' : email ? 'email' : 'none',
40	  };
41	}
42	
43	export function getUserId(): string {
44	  let globalConfig = readGlobalConfig();
45	  if (!globalConfig?.id) {
46	    const newId = crypto.randomUUID();
47	    globalConfig = { ...globalConfig, id: newId };
48	    writeGlobalConfig(globalConfig);
49	    return newId;
50	  }
51	
52	  return globalConfig.id;
53	}
54	
55	export function getUserEmail(): string | null {
56	  const globalConfig = readGlobalConfig();
57	  return globalConfig?.account?.email || null;
58	}
59	
60	export function setUserEmail(email: string) {
61	  const globalConfig = readGlobalConfig();
62	  const account = globalConfig?.account ?? {};
63	  account.email = email;
64	  const config: Partial<GlobalConfig> = { account };
65	  writeGlobalConfigPartial(config);
66	}
67	
68	export function clearUserEmail() {
69	  const globalConfig = readGlobalConfig();
70	  const account = globalConfig?.account ?? {};
71	  delete account.email;
72	  const config: Partial<GlobalConfig> = { account };
73	  writeGlobalConfigPartial(config);
74	}
