82	  const globalConfig = readGlobalConfig();
83	  const account = globalConfig?.account ?? {};
84	  account.emailNeedsValidation = needsValidation;
85	  const config: Partial<GlobalConfig> = { account };
86	  writeGlobalConfigPartial(config);
87	}
