115	export function isLoggedIntoCloud(): boolean {
116	  // Check if user has authenticated with Promptfoo Cloud
117	  // This supports both interactive (email-based) and non-interactive (API key) authentication
118	  // CI environments can authenticate via API keys, so we no longer exclude CI
119	  return getUserAuthInfo().isLoggedIntoCloud;
120	}
