140	 */
141	export async function checkEmailStatus(options?: {
142	  validate?: boolean;
143	}): Promise<EmailStatusResult> {
144	  const { default: telemetry } = await import('../telemetry');
145	  const ciMode = isCI();
146	  const userEmail = ciMode ? CI_PLACEHOLDER_EMAIL : getUserEmail();
147	
148	  if (!userEmail) {
149	    return {
150	      status: NO_EMAIL_STATUS,
151	      hasEmail: false,
152	      message: 'Redteam evals require email verification. Please enter your work email:',
153	    };
154	  }
155	
156	  if (ciMode) {
157	    // CI uses a synthetic placeholder to avoid interactive prompts. Treat it as
158	    // already validated so test runs do not depend on live account state.
159	    return {
160	      status: EmailValidationStatus.OK,
161	      hasEmail: true,
162	      email: userEmail,
163	    };
164	  }
165	
166	  try {
167	    const validateParam = options?.validate ? '&validate=true' : '';
168	    // Use longer timeout when validation is requested
169	    const timeout = options?.validate ? 3000 : 500;
170	
171	    // Log when we're validating the email since it can take a sec
172	    if (options?.validate) {
173	      logger.info(`Checking email...`);
174	    }
175	
176	    const host = getEnvString('PROMPTFOO_CLOUD_API_URL', 'https://api.promptfoo.app');
177	
178	    const resp = await fetchWithTimeout(
179	      `${host}/api/users/status?email=${encodeURIComponent(userEmail)}${validateParam}`,
180	      undefined,
181	      timeout,
182	    );
183	    const data = (await resp.json()) as {
184	      status: EmailValidationStatus;
185	      message?: string;
186	      error?: string;
187	    };
188	
189	    if (options?.validate) {
190	      const invalidStatuses: Set<EmailValidationStatus> = new Set([
191	        EmailValidationStatus.RISKY_EMAIL,
192	        EmailValidationStatus.DISPOSABLE_EMAIL,
193	        EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED,
194	      ]);
195	      if (invalidStatuses.has(data.status)) {
196	        if (data.status === EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED) {
197	          setUserEmailValidated(false);
198	          setUserEmailNeedsValidation(true);
199	        }
200	        // Tracking filtered emails via this telemetry endpoint for now to guage sensitivity of validation
201	        // We should take it out once we're happy with the sensitivity
202	        if (
203	          data.status === EmailValidationStatus.RISKY_EMAIL ||
204	          data.status === EmailValidationStatus.DISPOSABLE_EMAIL
205	        ) {
206	          await telemetry.saveConsent(userEmail, {
207	            source: 'filteredInvalidEmail',
208	          });
209	        }
210	      } else {
211	        setUserEmailValidated(true);
212	        // Track the validated email via telemetry
213	        await telemetry.saveConsent(userEmail, {
214	          source: 'promptForEmailValidated',
215	        });
216	      }
217	    }
218	
219	    return {
220	      status: data.status,
221	      message: data.message ?? data.error,
222	      email: userEmail,
223	      hasEmail: true,
224	    };
225	  } catch (e) {
226	    logger.debug(`Failed to check user status: ${e}`);
