135	function extractMessage(info: winston.Logform.TransformableInfo): string {
136	  if (typeof info.message === 'object' && info.message !== null && 'message' in info.message) {
137	    return typeof info.message.message === 'string'
138	      ? info.message.message
139	      : String(info.message.message);
140	  }
141	
142	  return typeof info.message === 'string' ? info.message : JSON.stringify(info.message);
143	}
