        if (
          opts.target &&
          UUID_REGEX.test(opts.target) &&
          (!configObj.targets || configObj.targets?.length === 0)
        ) {
          configObj.targets = [{ id: `${CLOUD_PROVIDER_PREFIX}${opts.target}`, config: {} }];
